"""Read the precise labels of figures 387–389 without treating a schematic as a scale drawing."""
import argparse
import json
from math import acos,atan2,cos,dist,pi,radians,sin,sqrt
from polygon_similarity_intro import entry,pair,rectangle,scaled
from rotated_circles_lines import diagram
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/similarity-figure-reading.json'


def source_quad(title,k=2,angle=100,w=6,h=4,cd=5):
    # Determine C from triangle BCD; choose the side of BD opposite A.
    c=radians(angle);bd=sqrt(w*w+h*h)
    bc=cd*cos(c)+sqrt(bd*bd-cd*cd*sin(c)**2)
    co=(bc*bc+bd*bd-cd*cd)/(2*bc*bd)
    direction=atan2(-h,w)+acos(max(-1,min(1,co)))
    p={'A':(0,0),'B':(0,h),'C':(bc*cos(direction),h+bc*sin(direction)),'D':(w,0)}
    return scaled(title,p,k,k)


def quadrilateral(part):
    scenes=[source_quad('Пропорциональная пара рисунка 387'),source_quad('Проверка чисел исходной пары'),source_quad('Авторская пара с новым масштабом',3,105)]
    if part=='а':
        task='Найди коэффициент подобия многоугольника ABCD относительно A₁B₁C₁D₁ по рисунку 387. Назови также коэффициент обратного сравнения.'
        proof='В исходной паре AD=6 и A₁D₁=12. При сравнении ABCD с A₁B₁C₁D₁ берём первую длину в числителе: k=6/12=1/2. В обратном порядке коэффициент равен 12/6=2. Прямо указывай направление сравнения, поскольку обе величины описывают одну пару фигур.'
        steps=[('Определи направление','Буквы со штрихом на этих моделях соответствуют индексу 1 в книге. Сначала выбери, какая фигура в числителе отношения.','Общие углы и одинаковый вид не задают направление дроби сами по себе.'),
               ('Вычисли обратное отношение','В исходной паре AD=6 и A′D′=12. Назови коэффициент большой фигуры относительно малой.','Если нужна большая фигура относительно малой, нельзя получить коэффициент меньше 1.'),
               ('Повтори при новом масштабе','В третьем авторском чертеже длины соответствующих оснований равны 6 и 18. Найди знаменатель несократимой дроби для малой фигуры относительно большой.','Не переноси число 2 из исходного рисунка: в новой паре другая длина большого основания.')]
        checks=[('Каков коэффициент большой фигуры относительно малой в исходной паре?','2','12÷6=2.'),('Каков знаменатель коэффициента малой фигуры относительно большой при 6 и 18?','3','6/18=1/3.')]
    elif part=='б':
        task='По рисунку 387 найди углы A₁ и C₁ большого четырёхугольника, используя соответствие с малым ABCD.'
        proof='В малом четырёхугольнике A — прямой угол, а C равен 100°. У подобного большого четырёхугольника A₁ соответствует A, а C₁ — C. Поэтому A₁=90°, C₁=100°. Число 2 меняет длины сторон, но не величины соответствующих углов.'
        steps=[('Выбери пары углов','A и A′ стоят у соответствующих концов оснований. C и C′ — вершины, лежащие между сторонами BC и CD и их образами.','Сопоставляй вершины по обходу, а не по положению относительно края экрана.'),
               ('Перенеси отметку угла','В первом и втором моделях угол C точно равен 100°. Определи C′. Прямой угол при A одновременно даёт величину A′.','Умножать угол на линейный коэффициент подобия не нужно.'),
               ('Проверь новое исходное число','В третьей авторской модели угол C изменён до 105°, а масштаб по длинам стал 3. Найди C′.','Решай по углу новой фигуры: число 100° принадлежит исходной задаче.') ]
        checks=[('Сколько градусов в C′ исходной пары?','100','Соответствующие углы равны.'),('Сколько градусов в C′ новой пары?','105','Поворот или увеличение не меняют углов.') ]
    else:
        task='На рисунке 387 найди длины A₁B₁ и CD. Даны AD=6, A₁D₁=12, AB=4 и C₁D₁=10.'
        proof='Большая фигура имеет коэффициент 2 относительно малой. Отсюда A₁B₁=2·AB=8. Для CD движемся в обратном направлении: CD=C₁D₁/2=10/2=5. Эти два перехода требуют разных действий, поскольку известные длины относятся к разным фигурам.'
        steps=[('Найди масштаб','Исходные основания 6 и 12 определяют отношение больших длин к малым. Найди, какая сторона большой фигуры соответствует AB.','У большой фигуры все четыре длины умножены на один и тот же коэффициент.'),
               ('Перейди от большой длины к малой','При C′D′=10 и коэффициенте 2 найди длину CD. Для второго ответа исходного задания умножь AB=4 на 2.','Применяй деление к известной большой длине и умножение к известной малой длине.'),
               ('Повтори с другими основаниями','В третьей схеме A′D′=18 при AD=6. Исходная AB по-прежнему 4. Найди новую A′B′.','Сначала пересчитай коэффициент, затем переходи к стороне.') ]
        checks=[('Чему равно CD при C′D′=10 в исходной паре?','5','10÷2=5.'),('Чему равно A′B′ при новом коэффициенте 3 и AB=4?','12','4·3=12.')]
    return entry(1299,part,[338],task,proof,steps,scenes,checks,
       'У подобных многоугольников соответствующие углы равны, а стороны умножаются на один положительный коэффициент.',
       'Выбери направление отношения по основаниям 6 и 12. Затем отдельно обрабатывай угол или длину.',
       'Штрих указывает вершину с индексом 1. Третья модель даёт самостоятельный повтор с другими данными.',refs=[130,131])


def pentagon(mode):
    # An exact convex side model and an exact convex angle model represent different exercises.
    a=(4.2*cos(radians(145)),4.2*sin(radians(145)));c=(3,5);d=(3,0);e=(0,0)
    if mode=='sides':
        radius=5.4;g=dist(a,c);along=(radius*radius-16+g*g)/(2*g);normal=sqrt(radius*radius-along*along)
        ux,uy=(c[0]-a[0])/g,(c[1]-a[1])/g
        b=(a[0]+along*ux-normal*uy,a[1]+along*uy+normal*ux)
    else:b=(a[0]+5.4*cos(radians(35)),a[1]+5.4*sin(radians(35)))
    return {'A':a,'B':b,'C':c,'D':d,'E':e}


def pentagons():
    scenes=[scaled('Соответствующие стороны и общий коэффициент',pentagon('sides'),5/3,5/3),
            scaled('Чтение всех пяти пар длин',pentagon('sides'),5/3,5/3,15),
            scaled('Отдельная проверка углов 70°, 90°, 145°',pentagon('angles'),1.3,1.3)]
    c=entry(1300,None,[338],'На рисунке 388 сравни подобные пятиугольники и найди x, y, z, t, α и β по подписанным сторонам и углам.',
       'Малой стороне 3 соответствует большая сторона 5. Все переходы от малого пятиугольника к большому умножают длины на 5/3. Поэтому x=9·3/5=27/5, y=4·5/3=20/3, z=5·5/3=25/3, t=7·3/5=21/5. По соответствующим меткам углов α=145°, β=70°. Две первые интерактивные схемы построены по длинам. В третьей отдельно реализованы указанные углы. Числа печатной схемы задают пропорции и пары углов для чтения; совместная точная постройка по всем отметкам не получается.',
       [('Закрепи единственную общую дробь','Сначала отметь нижнюю правую сторону: у малого пятиугольника она 3, у большого 5. От малого к большому умножай на 5/3, от большого к малому на 3/5.','Для x и t даны большие длины 9 и 7. Умножение на 5/3 сделало бы искомые малые стороны слишком длинными.'),
        ('Сопоставь четыре неизвестные стороны','В схемах длин A–B соответствует x и 9, B–C — 4 и y, C–D — 5 и z, E–A — t и 7. Запиши по каждой паре отдельное равенство.','Не округляй 20/3 или 25/3, если требуется точное значение. Умножение дроби на знаменатель позволяет проверить числитель.'),
        ('Прочитай углы отдельно','В третьем построении A соответствует углу 70°, E — углу 145°, а D — прямому. Перенеси подписи между соответствующими вершинами подобной пары.','Углы не умножаются на 5/3. В печатной схеме α стоит у малого E, а β — у большого A.')],
       scenes,[('Чему равно 3z при z=5·5/3?','25','Тройка сокращает знаменатель.'),('Сколько градусов в β у большого пятиугольника?','70','Это соответствующий угол малой фигуры.')],
       'Отношение большой стороны к малой равно 5/3; у соответствующих углов одно и то же число градусов.',
       'Отдельно выпиши пары длин и пары углов. Для каждой стороны подпиши направление перехода.',
       'A и E обозначают вершины с β и α; D — прямой угол. Первые две модели предназначены для измерения длин, последняя — для измерения углов.',refs=[131])
    return c


def classify(part):
    if part=='а':
        pts1=rectangle(5,2);pts2=rectangle(4,3)
        scenes=[scaled('Прямоугольники рисунка 389а',pts1,1,.5),scaled('Отрезки 2 и 1',pts1,1,.5,15),scaled('Новый прямоугольник 4×3 и его копия',pts2,2,2,16)]
        task='Установи по рисунку 389а, подобны ли прямоугольники F и F₁ с размерами 5×2 и 5×1.'
        proof='Прямоугольники не подобны. В каждом длинная сторона равна 5, но у коротких получается отношение 2/1=2. Если бы существовало подобие, отношение большей стороны к меньшей было бы одинаковым: 5/2 и 5/1 различны. Поворот на листе этот результат не изменит. Все четыре прямых угла у обеих фигур не обеспечивают пропорциональности сторон.'
        steps=[('Сравни пропорции','Нижние основания равны 5 у обеих фигур. Две высоты 2 и 1. Проверь обе пары, не ограничиваясь основаниями.','Равенство соответствующих углов недостаточно для подобия прямоугольников.'),
               ('Сравни высоты в одном направлении','Во второй схеме высоты большей по площади и меньшей фигур равны 2 и 1. Найди отношение 2 к 1 и сравни с отношением длинных сторон.','В обоих отношениях выбирай фигуры в одном порядке.'),
               ('Измени оба размера','В третьем примере оригинал 4×3 и получена его копия 8×6. Назови единый коэффициент большой фигуры относительно малой.','В этом новом примере изменилась и длинная, и короткая сторона.') ]
        checks=[('Чему равно отношение высот 2 к 1?','2','Оно отличается от отношения оснований 5/5.'),('Каков коэффициент для пары 4×3 и 8×6?','2','8/4=6/3=2.')]
    elif part=='б':
        h=sqrt(3);tri={'A':(0,0),'B':(h,0),'C':(0,1)}
        scenes=[scaled('Два прямоугольных треугольника',tri,2,2,35),scaled('Прямой угол и угол 30°',tri,1.5,1.5,-20),scaled('Новая пара при коэффициенте 3',tri,3,3,10)]
        task='По рисунку 389б сравни треугольники P и P₁. У каждого отмечены прямой угол и угол 30°.'
        proof='Треугольники подобны по двум углам: совпадают прямые углы и углы по 30°. Оставшиеся углы в обоих равны 60°. Конкретные длины с рисунка для этого вывода не требуются. Соответствуют вершины против соответствующих сторон, даже если второй треугольник изображён с другим наклоном.'
        steps=[('Проверь две пары углов','Сопоставь вершины с прямыми углами и с углами 30°. Для треугольников этого достаточно.','Воспользуйся признаком по двум углам именно треугольников.'),
               ('Восстанови оставшийся угол','Сумма углов треугольника 180°. Вычти 90° и 30°.','Последний угол не становится равным углу между сторонами только из-за положения фигуры на странице.'),
               ('Применяй к другим размерам','В третьем авторском примере короткий катет малой фигуры равен 1, коэффициент большой фигуры относительно малой равен 3. Назови короткий катет копии.','Число 3 относится к этому авторскому примеру. В исходной задаче спрашивают о самом факте подобия.') ]
        checks=[('Сколько градусов в третьем угле прямоугольного треугольника с углом 30°?','60','180−90−30=60.'),('Каков короткий катет копии в третьем примере?','3','1·3=3.')]
    else:
        def different(title,s):
            a={'A':(-2,0),'B':(-1,2),'C':(1,2),'D':(2,-1)}
            b={'E':(3,0),'F':(4,2),'G':(6,2),'H':(7,-1),'K':(4,-1)}
            return diagram(title,{k:(x*s,y*s) for k,(x,y) in {**a,**b}.items()},
                           [(g[i],g[(i+1)%len(g)]) for g in ('ABCD','EFGHK') for i in range(len(g))])
        scenes=[different('Четырёхугольник и пятиугольник',1),different('Отметь все пять вершин справа',1.6),different('Другой масштаб двух фигур',.8)]
        task='По рисунку 389в проверь, могут ли быть подобными многоугольники R и R₁ с разным числом вершин.'
        proof='R — четырёхугольник, а R₁ — пятиугольник. Для подобных многоугольников необходимо соответствие всех вершин и сторон по порядку обхода. Между четырьмя и пятью вершинами такого взаимно однозначного соответствия нет. Поэтому R и R₁ не подобны. Совпадение длин некоторых сторон, например подписанных 3 или 5, не устраняет различия числа вершин.'
        steps=[('Обойди каждую границу','Начни с одной вершины, посчитай каждую смену направления и остановись перед повторным счётом начальной вершины.','Не путай подписи длин у сторон с количеством сторон.'),
               ('Сосчитай вершины большей по числу сторон фигуры','На второй схеме справа E,F,G,H,K образуют один замкнутый обход. Сколько здесь вершин?','Точка, в которой обход закончился, уже была посчитана в начале.'),
               ('Измени масштаб и проверь разницу','В третьем чертеже длины изменены, но одна фигура по-прежнему четырёхугольник, другая пятиугольник. Какова разница в количестве их сторон?','Изменением масштаба невозможно превратить отдельную вершину выпуклого пятиугольника в отсутствующую вершину четырёхугольника.') ]
        checks=[('Сколько вершин у правой фигуры?','5','Пять разных поворотов границы.'),('На сколько различается число сторон?','1','5−4=1.')]
    return entry(1301,part,[338],task,proof,steps,scenes,checks,
       'Сначала сравни количество вершин. Для треугольников возможен признак по двум углам; для остальных многоугольников проверь пропорциональность сторон и равенство углов.',
       'Выбери проверку, подходящую именно к виду фигур в этом подпункте.',
       'Показаны собственные чертежи для чтения соответствий; новые числовые примеры отделены названием модели.',refs=[64,131])


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[*[quadrilateral(p) for p in 'абв'],pentagons(),*[classify(p) for p in 'абв']]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
